import{_ as t,o,c as r,ae as d}from"./chunks/framework.B2FZg54p.js";const a="/heidrun/experiments/web-doc-by-ai/documentation_images/files/more_options.png",b=JSON.parse('{"title":"Files sidebar section controls","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/files_sidebar_section_controls.md","filePath":"documentation/files_sidebar_section_controls.md"}'),n={name:"documentation/files_sidebar_section_controls.md"};function i(s,e,l,h,c,f){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="files-sidebar-section-controls" tabindex="-1">Files sidebar section controls <a class="header-anchor" href="#files-sidebar-section-controls" aria-label="Permalink to &quot;Files sidebar section controls&quot;">​</a></h1><p>Look up the controls, appearance choices, and row indicators of the Files sidebar section.</p><h2 id="header-buttons" tabindex="-1">Header buttons <a class="header-anchor" href="#header-buttons" aria-label="Permalink to &quot;Header buttons&quot;">​</a></h2><p>The header stays at the top while the rows scroll. The five buttons show only icons, in this order from left to right.</p><table tabindex="0"><thead><tr><th>Button</th><th>Icon</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>New file</strong></td><td>File with a plus sign</td><td>Opens a name box for an empty file in the selected destination.</td></tr><tr><td><strong>New folder</strong></td><td>Folder with a plus sign</td><td>Opens a name box for an empty folder in the selected destination.</td></tr><tr><td><strong>Refresh</strong></td><td>Circular arrow</td><td>Reads the folder tree again; disabled while the folder tree loads.</td></tr><tr><td><strong>Collapse all folders</strong></td><td>Square with a minus sign</td><td>Folds every folder.</td></tr><tr><td><strong>More options</strong></td><td>Three vertical dots</td><td>Opens the appearance choices for the folder tree.</td></tr></tbody></table><p><img src="'+a+'" alt="Files sidebar section header buttons with the More options menu open."></p><p>There is no button to unfold every folder.</p><h2 id="row-and-name-box-actions" tabindex="-1">Row and name box actions <a class="header-anchor" href="#row-and-name-box-actions" aria-label="Permalink to &quot;Row and name box actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td>Click a folder row</td><td>Selects the folder and folds or unfolds the folder, unless the folder is ignored.</td></tr><tr><td>Click a file row</td><td>Selects the file and opens the file in the large Git window.</td></tr><tr><td>Right-click a file row</td><td>Opens the file context menu without opening the large Git window.</td></tr><tr><td>Click empty space outside all rows</td><td>Clears the selection in the selected workspace.</td></tr><tr><td>Press <strong>Enter</strong> in the name box</td><td>Creates the file or folder for a valid, nonempty name; an error keeps the name box open.</td></tr><tr><td>Press <strong>Escape</strong> in the name box, or click outside the name box</td><td>Cancels creation.</td></tr></tbody></table><h2 id="more-options" tabindex="-1">More options <a class="header-anchor" href="#more-options" aria-label="Permalink to &quot;More options&quot;">​</a></h2><p>A check mark identifies the active choice in each group. The appearance choices are saved.</p><table tabindex="0"><thead><tr><th>Group</th><th>Choices</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Indentation</strong></td><td><strong>Small</strong>, <strong>Medium</strong>, <strong>Large</strong></td><td><strong>Medium</strong></td><td>The horizontal space added for each folder level.</td></tr><tr><td><strong>Row height</strong></td><td><strong>Compact</strong>, <strong>Comfortable</strong></td><td><strong>Comfortable</strong></td><td>The vertical space occupied by each row.</td></tr><tr><td><strong>Indent guides</strong></td><td><strong>Show</strong>, <strong>Hide</strong></td><td><strong>Show</strong></td><td>Whether lines mark the folder levels.</td></tr></tbody></table><h2 id="file-context-menu" tabindex="-1">File context menu <a class="header-anchor" href="#file-context-menu" aria-label="Permalink to &quot;File context menu&quot;">​</a></h2><p>A context menu is a small menu of actions for a row. These items are available for file rows only.</p><table tabindex="0"><thead><tr><th>Item</th><th>Copied text</th></tr></thead><tbody><tr><td><strong>Copy absolute path</strong></td><td>The full path of the file.</td></tr><tr><td><strong>Copy relative path</strong></td><td>The path of the file relative to the Git repository root, including when the workspace folder is a repository subfolder.</td></tr></tbody></table><p>See <a href="/heidrun/experiments/web-doc-by-ai/documentation/copy_a_file_path.html">Copy a file path</a> for examples and copying steps.</p><h2 id="folder-tree-indicators" tabindex="-1">Folder tree indicators <a class="header-anchor" href="#folder-tree-indicators" aria-label="Permalink to &quot;Folder tree indicators&quot;">​</a></h2><p>Folders appear before files, with each group in alphabetical order.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Meaning</th></tr></thead><tbody><tr><td>Right-pointing folder arrow</td><td>The folder is folded.</td></tr><tr><td>Downward-pointing folder arrow</td><td>The folder is unfolded.</td></tr><tr><td>Row with a blue outline</td><td>The selected file or folder; only one row is selected.</td></tr><tr><td><strong>M</strong></td><td>A modified file.</td></tr><tr><td><strong>A</strong></td><td>An added file.</td></tr><tr><td><strong>D</strong></td><td>A deleted file.</td></tr><tr><td><strong>R</strong></td><td>A renamed file.</td></tr><tr><td><strong>U</strong></td><td>A new file that Git does not track yet.</td></tr><tr><td>Dot on a folder row</td><td>Changes exist inside the folder.</td></tr></tbody></table><p>Changed-file letters appear at the right of the file row.</p><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Meaning</th></tr></thead><tbody><tr><td>Selected row</td><td>Each workspace keeps a separate selection. Returning to a workspace restores the selected row with the folders above the row unfolded.</td></tr><tr><td>Closing the large Git window</td><td>The selected row remains selected.</td></tr><tr><td>Changing the sidebar section</td><td>The selected row and the folded or unfolded state of folders are retained.</td></tr></tbody></table><h2 id="ignored-files" tabindex="-1">Ignored files <a class="header-anchor" href="#ignored-files" aria-label="Permalink to &quot;Ignored files&quot;">​</a></h2><p>The Files window is the project file browser opened with <strong>⌘P</strong>, as listed in <a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>. The <strong>Ignored files</strong> checkbox is below the file-name search field in the <strong>Files</strong> view on the left of the Files window.</p><p>The choice is saved and also affects the Files sidebar section. Folders excluded by <code>.gitignore</code> appear when the checkbox is selected, but cannot unfold.</p><p>See <a href="/heidrun/experiments/web-doc-by-ai/documentation/create_a_file_or_folder.html#create-the-file-or-folder">Create a file or folder</a> for empty-folder behaviour and <a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html#long-file-lists">Browse and open project files</a> for the long-list limitation.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html">Browse and open project files</a>: to find and view a file.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/create_a_file_or_folder.html">Create a file or folder</a>: to choose a destination and create an empty file or folder.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/copy_a_file_path.html">Copy a file path</a>: to copy either form of a file path.</li></ul>',28)])])}const g=t(n,[["render",i]]);export{b as __pageData,g as default};
